"""Generate docs/revision/MODEL_INPUT_AUDIT.md from run records, model metadata and the dataset manifests."""
import sys, json
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import torch
from src.cropxai.models import create_model, freeze_backbone
from src.cropxai.inputs import SPECS, TIF_BAND_ORDER, PRITHVI_TIF_INDEX
from generate_figures import complete_groups, MODEL_ORDER

def trainable(name,bands,classes):
    m,_=create_model(name,classes,False,bands); freeze_backbone(m)
    return sum(p.numel() for p in m.parameters() if p.requires_grad), sum(p.numel() for p in m.parameters())

def main():
    summary=json.loads(Path('results/processed/revision_summary.json').read_text()); groups=complete_groups(summary)
    ms=json.loads(Path('results/processed/dataset_manifest_ms.json').read_text()); rgb=json.loads(Path('results/processed/dataset_manifest.json').read_text())
    L=['# Model input audit','',f"Generated by `scripts/make_input_audit.py` from `results/processed/revision_summary.json` (source revision `{summary['current_source_revision'][:12]}`). Nothing below is typed by hand.",'',
       '## Per-model table','',
       '| Model | Checkpoint (verified SHA-256) | Dataset representation | Channels | Bands (tensor order) | Normalization | Resolution | Pretraining | Channel adaptation | Trainable / total params | Run IDs |','|---|---|---|---|---|---|---|---|---|---|---|']
    for g in groups:
        r=json.loads(Path('results/raw',g['run_ids'][0]+'.json').read_text()); md=r['model']; spec=SPECS[md['input_spec']]
        tr,tot=trainable(md['architecture'],md['bands'],10)
        norm=f"per-channel mean {[round(v,3) for v in spec.mean]}, std {[round(v,3) for v in spec.std]} ({'ImageNet statistics' if spec.name=='eurosat_rgb_jpeg' else 'Prithvi-EO-1.0 pretraining statistics, DN units'})"
        L.append(f"| {md['architecture']} | {md['weights']}; `{md['checkpoint_sha256']}` | {spec.name} | {md['channels']} | {', '.join(md['bands'])} | {norm} | {md['size']}x{md['size']} (bilinear from 64x64) | {md['pretraining']} | {md['channel_adaptation']} | {tr:,} / {tot:,} | {', '.join(g['run_ids'])} |")
    L+=['','Evidence for fine-tuning policy: every run uses `finetune_mode = frozen_backbone_eval` (all backbone parameters fixed, BatchNorm/dropout in eval mode); only the linear head `fc` is trained (Adam, lr 1e-3, batch 32, 5 epochs). Trainable counts are computed by building the registered model and applying `freeze_backbone`.','']
    L+=['## Dataset representations','',
        f"* **RGB cohort** - `{rgb['dataset']}`, root `{rgb['root']}`, {rgb['n']} JPEG images (64x64, mode RGB), split id `{rgb['split_id'][:12]}`. The bands of the JPEG release are R,G,B (Sentinel-2 B04,B03,B02) after the upstream provider's unknown contrast stretch; the JPEGs carry no band metadata.",
        f"* **Six-band cohort** - `{ms['dataset']}`, root `{ms['root']}`, {ms['n']} GeoTIFFs (13 bands, uint16, 64x64), split id `{ms['split_id'][:12]}` (rgb split id `{ms['rgb_split_id'][:12]}`). Rows follow the JPEG split by file stem, so both cohorts evaluate the identical 4,050 test items (verified by `identical_test_items` in the compliance report only within a cohort; cross-cohort equality is checked by the paired analysis).",'',
        '## Sentinel-2 GeoTIFF band order (empirical)','',
        'The GeoTIFFs carry no band descriptions. The order inferred and then asserted by `src/cropxai/data.py::band_order_evidence` is:','',
        '`'+', '.join(f'{i}:{b}' for i,b in enumerate(TIF_BAND_ORDER))+'`','',
        'This differs from the nominal listing (B8A before B09). Evidence on 400 deterministic patches:','']
    ev=ms['band_order_evidence']['checks']
    L+=[f"* corr(B8A, B08) = {ev['corr_B8A_B08']:.3f} (>0.95 required) versus corr(B09, B08) = {ev['corr_B09_B08']:.3f};",f"* mean B10 (cirrus) = {ev['mean_B10_cirrus_DN']:.1f} DN (<100 required); mean B11 = {ev['mean_B11_DN']:.0f} > mean B12 = {ev['mean_B12_DN']:.0f}.",'',
        'Under the nominal order, index 8 would have been selected as B8A; it is in fact the water-vapour band B09 (correlation 0.75 with B08). The unit test `tests/test_revision_v2.py::BandOrderEvidenceTests` shows the audit fails for a swapped file.','',
        '## Prithvi-EO-1.0-100M band adaptation (R3.4)','',
        '| Prithvi channel (HLS L30 name) | Meaning | Sentinel-2 band used | GeoTIFF index | Pretraining mean (DN) | std (DN) |','|---|---|---|---|---|---|']
    from src.cropxai.inputs import PRITHVI_HLS_BANDS, PRITHVI_S2_BANDS, PRITHVI_MEAN, PRITHVI_STD
    meaning=['Blue','Green','Red','Narrow NIR','SWIR 1','SWIR 2']
    for i in range(6): L.append(f"| {PRITHVI_HLS_BANDS[i]} | {meaning[i]} | {PRITHVI_S2_BANDS[i]} | {PRITHVI_TIF_INDEX[i]} | {PRITHVI_MEAN[i]:.1f} | {PRITHVI_STD[i]:.1f} |")
    L+=['','* No input parameter is added or re-initialized: the six pretrained channels receive the six corresponding Sentinel-2 bands (`channel_adaptation = none`).',
        '* The pretrained model takes three time steps. A single acquisition is supplied (T=1); the 3D sin-cos position-embedding table is rebuilt for one frame and **verified equal** to the CLS + first-frame rows of the checkpoint table (`pos_embed_equals_checkpoint_frame0`, asserted at model construction).',
        '* Domain shift that is NOT corrected: the EuroSAT processing level is not stated in the dataset paper but appears to be Level-1C top-of-atmosphere (the cirrus band B10, absent from Level-2A products, is present with mean 12 DN), whereas Prithvi was pretrained on HLS surface reflectance; EuroSAT patches are 64x64 and are bilinearly upsampled to the 224x224 pretraining size; Sentinel-2 B8A/B11/B12 are used for HLS NIR-narrow/SWIR1/SWIR2 without band-pass or BRDF harmonization.',
        '* Classification head: linear layer on the mean of final-layer patch tokens (CLS excluded), trained on frozen features. This differs from the segmentation/fine-tuning recipes published for Prithvi and should not be compared with them.','',
        '## Are all models on the same bands? (R3.5)','',
        '**No.** The three ImageNet-pretrained models consume RGB (3 channels); Prithvi consumes six bands from the GeoTIFF files. The two cohorts share the split and the test items but differ in input information, pretraining data and corruption units. Cross-cohort rankings are therefore reported as confounded. A controlled common-input comparison is not available: ImageNet models cannot consume the missing bands without an unvalidated input adapter, and Prithvi cannot consume RGB-only input without synthetic channels. This limitation is stated in the manuscript.','']
    Path('docs/revision/MODEL_INPUT_AUDIT.md').write_text('\n'.join(L)+'\n'); print('written docs/revision/MODEL_INPUT_AUDIT.md')
if __name__=='__main__': main()
